import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.SynchronousQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Supplier;

public class Solution {
    static class RejeitadoException extends RuntimeException {
        RejeitadoException(String message) {
            super(message);
        }
    }

    static class ExecutorLimitado implements AutoCloseable {
        private final ThreadPoolExecutor executor;
        private final AtomicLong concluidos = new AtomicLong();
        private final AtomicLong rejeitados = new AtomicLong();
        private final AtomicBoolean fechado = new AtomicBoolean();

        ExecutorLimitado(int concorrencia, int capacidadeFila) {
            if (concorrencia <= 0) {
                throw new IllegalArgumentException("concorrencia deve ser positiva");
            }
            if (capacidadeFila < 0) {
                throw new IllegalArgumentException("capacidadeFila nao pode ser negativa");
            }
            BlockingQueue<Runnable> fila = capacidadeFila == 0
                    ? new SynchronousQueue<>()
                    : new ArrayBlockingQueue<>(capacidadeFila);
            this.executor = new ThreadPoolExecutor(
                    concorrencia, concorrencia, 0L, TimeUnit.MILLISECONDS, fila,
                    runnable -> {
                        var thread = new Thread(runnable, "bulkhead-" + System.nanoTime());
                        thread.setDaemon(true);
                        return thread;
                    },
                    (runnable, pool) -> {
                        rejeitados.incrementAndGet();
                        throw new RejectedExecutionException("fila cheia");
                    });
        }

        <T> CompletableFuture<T> submit(Supplier<T> tarefa) {
            if (tarefa == null) {
                throw new IllegalArgumentException("tarefa obrigatoria");
            }
            if (fechado.get()) {
                rejeitados.incrementAndGet();
                return CompletableFuture.failedFuture(
                        new RejeitadoException("executor fechado"));
            }
            try {
                return CompletableFuture.supplyAsync(() -> {
                    try {
                        return tarefa.get();
                    } finally {
                        concluidos.incrementAndGet();
                    }
                }, executor);
            } catch (RejectedExecutionException rejeitado) {
                return CompletableFuture.failedFuture(
                        new RejeitadoException("fila cheia"));
            }
        }

        int ativos() {
            return executor.getActiveCount();
        }

        int naFila() {
            return executor.getQueue().size();
        }

        long concluidos() {
            return concluidos.get();
        }

        long rejeitados() {
            return rejeitados.get();
        }

        @Override
        public void close() {
            if (!fechado.compareAndSet(false, true)) {
                return;
            }
            executor.shutdown();
            try {
                if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }
    }
}

