import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;

class SolutionTest {
    @Test void executaTarefasEAtualizaMetricas() throws Exception {
        try (var executor = new Solution.ExecutorLimitado(2, 4)) {
            var a = executor.submit(() -> 10);
            var b = executor.submit(() -> 20);

            assertEquals(10, a.get(1, TimeUnit.SECONDS));
            assertEquals(20, b.get(1, TimeUnit.SECONDS));
            assertEquals(2, executor.concluidos());
            assertEquals(0, executor.rejeitados());
        }
    }

    @Test void respeitaConcorrenciaMaxima() throws Exception {
        var executor = new Solution.ExecutorLimitado(2, 5);
        var iniciadas = new CountDownLatch(2);
        var liberar = new CountDownLatch(1);

        java.util.function.Supplier<Integer> tarefa = () -> {
            iniciadas.countDown();
            try {
                liberar.await();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
            return 1;
        };

        var f1 = executor.submit(tarefa);
        var f2 = executor.submit(tarefa);
        var f3 = executor.submit(tarefa);

        assertTrue(iniciadas.await(1, TimeUnit.SECONDS));
        assertEquals(2, executor.ativos());
        assertEquals(1, executor.naFila());

        liberar.countDown();

        assertEquals(1, f1.get(1, TimeUnit.SECONDS));
        assertEquals(1, f2.get(1, TimeUnit.SECONDS));
        assertEquals(1, f3.get(1, TimeUnit.SECONDS));
        assertEquals(3, executor.concluidos());
        executor.close();
    }

    @Test void rejeitaQuandoFilaSaturada() throws Exception {
        var executor = new Solution.ExecutorLimitado(1, 1);
        var iniciada = new CountDownLatch(1);
        var liberar = new CountDownLatch(1);

        var primeira = executor.submit(() -> {
            iniciada.countDown();
            try {
                liberar.await();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
            return 1;
        });
        assertTrue(iniciada.await(1, TimeUnit.SECONDS));

        var segunda = executor.submit(() -> 2);
        var terceira = executor.submit(() -> 3);

        var erro = assertThrows(ExecutionException.class,
                () -> terceira.get(1, TimeUnit.SECONDS));
        assertTrue(erro.getCause() instanceof Solution.RejeitadoException);
        assertEquals(1, executor.rejeitados());

        liberar.countDown();
        assertEquals(1, primeira.get(1, TimeUnit.SECONDS));
        assertEquals(2, segunda.get(1, TimeUnit.SECONDS));
        executor.close();
    }

    @Test void excecaoDaTarefaPropagaEContaConcluido() throws Exception {
        try (var executor = new Solution.ExecutorLimitado(1, 1)) {
            var falha = executor.submit(() -> {
                throw new IllegalStateException("boom");
            });

            var erro = assertThrows(ExecutionException.class,
                    () -> falha.get(1, TimeUnit.SECONDS));
            assertTrue(erro.getCause() instanceof IllegalStateException);
            assertEquals(1, executor.concluidos());
        }
    }

    @Test void closeEsperaTarefasEmExecucao() throws Exception {
        var executor = new Solution.ExecutorLimitado(1, 1);
        var iniciada = new CountDownLatch(1);
        var liberar = new CountDownLatch(1);

        var tarefa = executor.submit(() -> {
            iniciada.countDown();
            try {
                liberar.await();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
            return 1;
        });
        assertTrue(iniciada.await(1, TimeUnit.SECONDS));

        var closer = new Thread(executor::close);
        closer.start();
        Thread.sleep(50);
        assertTrue(closer.isAlive());

        liberar.countDown();
        closer.join(2000);
        assertFalse(closer.isAlive());
        assertEquals(1, tarefa.get(1, TimeUnit.SECONDS));

        var recusada = executor.submit(() -> 2);
        var erro = assertThrows(ExecutionException.class,
                () -> recusada.get(1, TimeUnit.SECONDS));
        assertTrue(erro.getCause() instanceof Solution.RejeitadoException);
    }

    @Test void validaArgumentos() {
        assertThrows(IllegalArgumentException.class,
                () -> new Solution.ExecutorLimitado(0, 1));
        assertThrows(IllegalArgumentException.class,
                () -> new Solution.ExecutorLimitado(1, -1));
        try (var executor = new Solution.ExecutorLimitado(1, 1)) {
            assertThrows(IllegalArgumentException.class, () -> executor.submit(null));
        }
    }
}
